import { mkdirSync } from 'node:fs';
import path from 'node:path';
import { DatabaseSync } from 'node:sqlite';
import { migrateDatabase } from './migrate.js';

export interface AppDatabase {
  readonly raw: DatabaseSync;
  transaction<T>(operation: () => T): T;
  close(): void;
}

export interface DatabaseOptions {
  path: string;
  migrationsDirectory?: string;
}

export function openDatabase(options: DatabaseOptions): AppDatabase {
  if (options.path !== ':memory:') mkdirSync(path.dirname(options.path), { recursive: true });
  const raw = new DatabaseSync(options.path);
  raw.exec('PRAGMA foreign_keys = ON');
  raw.exec('PRAGMA busy_timeout = 5000');
  if (options.path !== ':memory:') raw.exec('PRAGMA journal_mode = WAL');

  try {
    migrateDatabase(raw, options.migrationsDirectory);
  } catch (error) {
    raw.close();
    throw error;
  }

  let closed = false;
  return {
    raw,
    transaction<T>(operation: () => T): T {
      raw.exec('BEGIN IMMEDIATE');
      try {
        const result = operation();
        raw.exec('COMMIT');
        return result;
      } catch (error) {
        raw.exec('ROLLBACK');
        throw error;
      }
    },
    close(): void {
      if (!closed) {
        closed = true;
        raw.close();
      }
    },
  };
}
CREATE TABLE bookmarks (
  id TEXT PRIMARY KEY NOT NULL,
  url TEXT NOT NULL,
  normalized_url TEXT NOT NULL UNIQUE,
  title TEXT NOT NULL CHECK (length(trim(title)) BETWEEN 1 AND 300),
  description TEXT CHECK (description IS NULL OR length(description) <= 2000),
  icon_path TEXT,
  notes TEXT CHECK (notes IS NULL OR length(notes) <= 10000),
  read_later INTEGER NOT NULL DEFAULT 0 CHECK (read_later IN (0, 1)),
  is_read INTEGER NOT NULL DEFAULT 0 CHECK (is_read IN (0, 1)),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  CHECK (read_later = 1 OR is_read = 0)
) STRICT;

CREATE TABLE tags (
  id INTEGER PRIMARY KEY,
  display_name TEXT NOT NULL CHECK (length(trim(display_name)) BETWEEN 1 AND 100),
  normalized_name TEXT NOT NULL UNIQUE
) STRICT;

CREATE TABLE bookmark_tags (
  bookmark_id TEXT NOT NULL REFERENCES bookmarks(id) ON DELETE CASCADE,
  tag_id INTEGER NOT NULL REFERENCES tags(id) ON DELETE CASCADE,
  PRIMARY KEY (bookmark_id, tag_id)
